generation.hcl:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket that must block all public access."
  type        = string
  default     = "demo-payroll-exports"

  validation {
    condition     = length(var.bucket_name) >= 3 && length(var.bucket_name) <= 63
    error_message = "bucket_name must be between 3 and 63 characters."
  }
}

data "aws_caller_identity" "current" {}

# Fixes live-e2e-s3-8-demo: S3 bucket is not configured to block public access
resource "aws_s3_bucket_public_access_block" "stratogent_demo_payroll_exports" {
  bucket                  = var.bucket_name
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Account-level Block Public Access to prevent future public exposure in this prod account
resource "aws_s3_account_public_access_block" "account_level" {
  account_id              = data.aws_caller_identity.current.account_id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

output "protected_bucket_name" {
  description = "Bucket on which Block Public Access is now enforced."
  value       = aws_s3_bucket_public_access_block.stratogent_demo_payroll_exports.bucket
}

output "account_level_block_enabled" {
  description = "Whether account-level Block Public Access is enforced."
  value       = true
}
